Уже проверенные внешние пары равны. После несовпадения возвращаем false, после схождения границ — true.

func pairIndices(_ values: [Int], target: Int) -> (Int, Int)? {
    var left = 0
    var right = values.count - 1
    while left < right {
        let sum = values[left] + values[right]
        if sum == target { return (left, right) }
        if sum < target { left += 1 } else { right -= 1 }
    }
    return nil
}
let result = pairIndices([1, 3, 4, 8], target: 7)
assert(result?.0 == 1 && result?.1 == 2)
assert(pairIndices([3], target: 6) == nil)
assert(pairIndices([], target: 6) == nil)

Направление движения следует из сортировки. left<right сохраняет два разных элемента; целочисленная сумма безопасна в заданных границах.

