При новом элементе write продвигается после записи. Неудалённый хвост намеренно вне возвращённого префикса.

func isCompactPalindrome(_ text: String) -> Bool {
    let characters = Array(text.filter { $0 != " " })
    var left = 0
    var right = characters.count - 1
    while left < right {
        guard characters[left] == characters[right] else { return false }
        left += 1
        right -= 1
    }
    return true
}
assert(isCompactPalindrome("а роза упала на лапу азора"))
assert(isCompactPalindrome("  "))
assert(!isCompactPalindrome("А а"))
assert(!isCompactPalindrome("а\tа а"))

Фильтрация соответствует точному контракту. lowercased и широкое удаление whitespace не добавлены незаметно.

func reverseCharacters(_ text: String) -> String {
    var characters = Array(text)
    var left = 0
    var right = characters.count - 1
    while left < right {
        characters.swapAt(left, right)
        left += 1
        right -= 1
    }
    return String(characters)
}
assert(reverseCharacters("А👨‍👩‍👧‍👦Б") == "Б👨‍👩‍👧‍👦А")
assert(reverseCharacters("").isEmpty)
assert(reverseCharacters("а") == "а")

Новая операция переставляет крайние Character целиком. Условие чтения осталось тем же, результат преобразуется обратно в String.
